module.exports = function (RED) {
    function ActionNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        node.action_name = config.action_name;
        node.action_location = config.action_location;
        node.action_param = config.action_param;

        node.on("input", function (msg, send, done) {
            let locations = node.action_location.split(",").map(x => x.trim());

            let action = {
                action_name: node.action_name,
                action_location: locations,
                action_param: {}
            };

            try {
                action.action_param = JSON.parse(node.action_param || "{}");
            } catch (e) {
                node.error("Invalid JSON in action_param", e);
                return;
            }

            msg.action = action;
            send(msg);
            done();
        });
    }

    RED.nodes.registerType("Action", ActionNode);
};